  "content": "1|import { useState } from 'react';
2|import {
3|  useCreateServerFunctionMutation,
4|  useDeleteServerFunctionMutation,
5|  useUpdateBuiltinServerFunctionMutation,
6|  useUpdateServerFunctionMutation,
7|} from '../../../shared/api/queries/server-functions';
8|import { DEFAULT_SERVER_FUNCTION_LANGUAGE } from '../constants';
9|import { createScriptDraftDefaults } from '../lib/scriptDraftDefaults';
10|import { buildBuiltinFunctionMetadataPayload, buildManagedFunctionPayload } from '../mappers';
11|import { isPackageServerFunction } from '../../../shared/api/contracts/server-functions/packageFunctions';
12|import type { FunctionAccessControl } from '../../../shared/api/contracts/server-functions/accessControl';
13|import {
14|  buildServerFunctionCatalogPath,
15|  buildServerFunctionPreviewPath,
16|  isServerFunctionIdentityTaken,
17|  normalizeServerFunctionFolder,
18|  normalizeServerFunctionName,
19|  suggestDuplicateServerFunctionName,
20|} from '../lib/duplicateServerFunctionIdentity';
21|import { buildServerFunctionTemplate } from '../templates';
22|import type { ServerFunctionItem } from '../types';
23|import {
24|  readServerFunctionCatalogTags,
25|  withServerFunctionCatalogTags,
26|} from '../../../shared/lib/serverFunctionCatalogTags';
27|import { normalizeCatalogTags } from '../../../shared/lib/catalogTags';
28|import { clearServerFunctionDraft, patchServerFunctionDraft } from './serverFunctionDraftCache';
29|import type { ServerFunctionCatalogState } from './useServerFunctionCatalog';
30|import type { ServerFunctionEditorState } from './useServerFunctionEditor';
31|import type { ServerFunctionSettingsState } from './useServerFunctionSettings';
32|
33|const DEFAULT_CUSTOM_FOLDER = 'general';
34|
35|const cloneAccessControl = (accessControl: FunctionAccessControl): FunctionAccessControl => ({
36|  ...accessControl,
37|  allowRoles: [...accessControl.allowRoles],
38|  allowUsers: [...accessControl.allowUsers],
39|  denyRoles: [...accessControl.denyRoles],
40|  denyUsers: [...accessControl.denyUsers],
41|});
42|
43|const cloneServerFunctionForAccess = (source: ServerFunctionItem): ServerFunctionItem => ({
44|  ...source,
45|  accessControl: cloneAccessControl(source.accessControl),
46|});
47|
48|const cloneServerFunctionForSettings = (source: ServerFunctionItem): ServerFunctionItem => ({
49|  ...source,
50|  accessControl: cloneAccessControl(source.accessControl),
51|  metadataJson: source.metadataJson ? structuredClone(source.metadataJson) : null,
52|  hooks: source.hooks ? structuredClone(source.hooks) : source.hooks,
53|});
54|
55|type UseServerFunctionActionsInput = {
56|  catalog: ServerFunctionCatalogState;
57|  editor: ServerFunctionEditorState;
58|  settings: ServerFunctionSettingsState;
59|  addLog: (msg: string, type?: 'info' | 'success' | 'warn') => void;
60|  showToast: (type: 'success' | 'error', text: string) => void;
61|};
62|
63|export function useServerFunctionActions({ catalog, editor, settings, addLog, showToast }: UseServerFunctionActionsInput) {
64|  const createServerFunctionMutation = useCreateServerFunctionMutation();
65|  const updateServerFunctionMutation = useUpdateServerFunctionMutation();
66|  const updateBuiltinServerFunctionMutation = useUpdateBuiltinServerFunctionMutation();
67|  const deleteServerFunctionMutation = useDeleteServerFunctionMutation();
68|
69|  const [isCreateOpen, setIsCreateOpen] = useState(false);
70|  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
71|  const [settingsTarget, setSettingsTarget] = useState<ServerFunctionItem | null>(null);
72|  const [isSavingSettings, setIsSavingSettings] = useState(false);
73|  const [isAccessOpen, setIsAccessOpen] = useState(false);
74|  const [accessTarget, setAccessTarget] = useState<ServerFunctionItem | null>(null);
75|  const [isSavingAccess, setIsSavingAccess] = useState(false);
76|  const [isHooksOpen, setIsHooksOpen] = useState(false);
77|  const [newFuncName, setNewFuncName] = useState('');
78|  const [newFuncTags, setNewFuncTags] = useState<string[]>([]);
79|  const [newFuncMethod, setNewFuncMethod] = useState<'GET' | 'POST' | 'PUT' | 'DELETE'>('GET');
80|  const [idToDelete, setIdToDelete] = useState<string | null>(null);
81|  const [isCreatingFromDraft, setIsCreatingFromDraft] = useState(false);
82|  const [isDuplicateOpen, setIsDuplicateOpen] = useState(false);
83|  const [duplicateSource, setDuplicateSource] = useState<ServerFunctionItem | null>(null);
84|  const [duplicateName, setDuplicateName] = useState('');
85|  const [duplicateTags, setDuplicateTags] = useState<string[]>([]);
86|  const [duplicateError, setDuplicateError] = useState<string | null>(null);
87|  const [isDuplicating, setIsDuplicating] = useState(false);
88|  const [isRenameOpen, setIsRenameOpen] = useState(false);
89|  const [renameSource, setRenameSource] = useState<ServerFunctionItem | null>(null);
90|  const [renameName, setRenameName] = useState('');
91|  const [renameTags, setRenameTags] = useState<string[]>([]);
92|  const [renameError, setRenameError] = useState<string | null>(null);
93|  const [isRenaming, setIsRenaming] = useState(false);
94|
95|  const openCreateDialog = () => {
96|    setNewFuncName('');
97|    setNewFuncTags([]);
98|    setNewFuncMethod('GET');
99|    setIsCreateOpen(true);
100|  };
101|
102|  const handleCreateFunction = async () => {
103|    if (!newFuncName.trim()) return;
104|
105|    const folderSlug = DEFAULT_CUSTOM_FOLDER;
106|    const nameSlug = normalizeServerFunctionName(newFuncName);
107|    if (!nameSlug) {
108|      showToast('error', 'Name is required.');
109|      return;
110|    }
111|    if (isServerFunctionIdentityTaken(catalog.functions, folderSlug, nameSlug)) {
112|      showToast('error', `A function named "${nameSlug}" already exists.`);
113|      return;
114|    }
115|
116|    const path = buildServerFunctionCatalogPath(nameSlug);
117|    const newId = `fn-${Math.random().toString(36).substring(2, 9)}`;
118|    const catalogTags = normalizeCatalogTags(newFuncTags);
119|
120|    const newFn: ServerFunctionItem = {
121|      id: newId,
122|      name: nameSlug,
123|      folder: folderSlug,
124|      method: newFuncMethod,
125|      path,
126|      code: buildServerFunctionTemplate(newFuncMethod, path, nameSlug),
127|      language: DEFAULT_SERVER_FUNCTION_LANGUAGE,
128|      testPayload: `{\n  "payload": "Default template input data"\n}`,
129|      memoryLimit: settings.globalDefaultRAM,
130|      timeoutMs: settings.globalDefaultTimeout,
131|      runtimeVersion: settings.globalDefaultVMMode,
132|      useGlobalConfig: true,
133|      enableLogs: true,
134|      cacheEnabled: false,
135|      cacheTtlMs: 3600000,
136|      accessControl: { allowRoles: [], allowUsers: [], denyRoles: [], denyUsers: [] },
137|      metadataJson: withServerFunctionCatalogTags(null, catalogTags),
138|      ...createScriptDraftDefaults(),
139|    };
140|
141|    try {
142|      const { response, data } = await createServerFunctionMutation.mutateAsync(buildManagedFunctionPayload(newFn));
143|      if (!response.ok) {
144|        throw new Error(data?.error || 'Failed to create function in API.');
145|      }
146|
147|      newFn.id = String(data.id || newId);
148|      catalog.upsertCatalogFunction(newFn);
149|      catalog.setActiveId(newFn.id);
150|    } catch (error: any) {
151|      const message = error?.message || 'Failed to create function.';
152|      addLog(message, 'warn');
153|      showToast('error', message);
154|      return;
155|    }
156|    setNewFuncName('');
157|    setNewFuncTags([]);
158|    setIsCreateOpen(false);
159|
160|    addLog(`Created new dynamic proxy mapping at: ${path}`, 'success');
161|    showToast('success', `Created edge route ${path}`);
162|  };
163|
164|  const handleBulkApply = () => {
165|    catalog.filteredFunctions.forEach((fn) => {
166|      if (fn.isBuiltIn) {
167|        return;
168|      }
169|      patchServerFunctionDraft(catalog.queryClient, fn.id, {
170|        runtimeVersion: settings.bulkVMMode,
171|        memoryLimit: settings.bulkRAM,
172|        timeoutMs: settings.bulkTimeout,
173|      });
174|    });
175|    catalog.bumpDraftRevision();
176|
177|    addLog(`Bulk updated ${catalog.filteredFunctions.length} ${catalog.filteredFunctions.length === 1 ? 'route' : 'routes'} VM config: Mode=${settings.bulkVMMode}, RAM=${settings.bulkRAM}MB, Timeout=${settings.bulkTimeout}ms.`, 'success');
178|
179|    const currentIsMatched = catalog.filteredFunctions.some((f) => f.id === catalog.activeId);
180|    if (currentIsMatched) {
181|      settings.setTestVMMode(settings.bulkVMMode);
182|      settings.setTestRAM(settings.bulkRAM);
183|      settings.setTestTimeout(settings.bulkTimeout);
184|    }
185|
186|    settings.setIsBulkOpen(false);
187|  };
188|
189|  const handleCreateFromDraft = async (identityOverride?: { folder: string; name: string }) => {
190|    const rawName = identityOverride?.name ?? editor.draftFn.name;
191|    if (!rawName.trim() || isCreatingFromDraft) return;
192|
193|    const folderSlug = DEFAULT_CUSTOM_FOLDER;
194|    const nameSlug = normalizeServerFunctionName(rawName);
195|    if (!nameSlug) return;
196|    const path = buildServerFunctionCatalogPath(nameSlug);
197|    const code = editor.draftCodeIsAutoGeneratedRef.current
198|      ? buildServerFunctionTemplate(editor.draftFn.method, path)
199|      : editor.draftFn.code;
200|    const newId = `fn-${Math.random().toString(36).substring(2, 9)}`;
201|
202|    const newFn: ServerFunctionItem = {
203|      id: newId,
204|      name: nameSlug,
205|      folder: folderSlug,
206|      method: editor.draftFn.method,
207|      path,
208|      code,
209|      language: editor.draftFn.language,
210|      testPayload: editor.draftFn.testPayload,
211|      memoryLimit: editor.draftFn.memoryLimit,
212|      timeoutMs: editor.draftFn.timeoutMs,
213|      runtimeVersion: editor.draftFn.runtimeVersion,
214|      useGlobalConfig: editor.draftFn.useGlobalConfig,
215|      enableLogs: editor.draftFn.enableLogs,
216|      isBuiltIn: editor.draftFn.isBuiltIn || false,
217|      cacheEnabled: editor.draftFn.cacheEnabled,
218|      cacheTtlMs: editor.draftFn.cacheTtlMs,
219|      accessControl: editor.draftFn.accessControl,
220|      engineType: editor.draftFn.engineType ?? 'SANDBOX_JS',"
}
